class Solution {
public:
    int divide(int dividend, int divisor) {
        bool negative = (dividend < 0) ^ (divisor < 0);
        long long a = dividend < 0 ? -(long long)dividend : (long long)dividend;
        long long d = divisor  < 0 ? -(long long)divisor  : (long long)divisor;
        long long q = 0;
        for (int i = 31; i >= 0; --i) {
            if ((a >> i) >= d) {
                a -= (d << i);
                q |= (1LL << i);
            }
        }
        if (negative) q = -q;
        if (q > INT_MAX) q = INT_MAX;
        if (q < INT_MIN) q = INT_MIN;
        return (int)q;
    }
};
